<script setup lang="ts">
import {ref,onMounted} from 'vue';
import ReaderTicket from './ReaderTicket.vue';
const props=defineProps<{api:(path:string,method?:string,body?:any)=>Promise<any>,can:(permission:string)=>boolean,isAdmin?:boolean}>();
const directoryOpen=ref(false),directorySource=ref('active_directory'),directoryQuery=ref(''),directoryResults=ref<any[]>([]),directorySearched=ref(false),directoryTruncated=ref(false);
const accounts=ref<any[]|null>(null),accountId=ref<number|null>(null);
async function accountOptions(){await run(async()=>{accounts.value=await props.api('/circulation/accounts');accountId.value=card.value.user_id||null;});}
async function linkAccount(){await run(async()=>{await props.api('/circulation/readers/'+card.value.id+'/account','POST',{request_key:crypto.randomUUID(),user_id:accountId.value});accounts.value=null;notice.value='Учётная запись читателя связана';});}
const sourceLabels:Record<string,string>={active_directory:'Active Directory',platonus:'Platonus','platonus-personal':'Персональные данные Platonus',csv:'CSV',manual:'Вручную',nightly:'Ночное обновление'};
const missingLabels:Record<string,string>={phone:'телефон',email:'email',faculty:'факультет',photo:'фото',iin:'ИИН',birth_date:'дата рождения'};
const runLabels:Record<string,string>={success:'Завершено',error:'Ошибка',dry_run:'Предварительная проверка',running:'Выполняется'};
const problemLabels:Record<string,string>={iin_birth_mismatch:'ИИН не соответствует дате рождения в источнике',duplicate_iin:'ИИН уже связан с другим читателем',invalid_identity:'Некорректный идентификатор',duplicate_source_identity:'Повтор идентификатора в источнике',unconfirmed_cross_source_link:'Связь AD и Platonus не подтверждена',ambiguous_cross_source_link:'Неоднозначная связь AD и Platonus',missing_name:'Не указано ФИО',invalid_personal_or_profile_data:'Проверьте персональные данные и поля карточки'};
const emit=defineEmits<{visit:[code:string]}>();
const fields:[string,string,string?][]=[['full_name','ФИО'],['email','Email'],['login','Логин источника'],['phone','Телефон'],['additional_email','Дополнительный email'],['faculty','Факультет'],['department','Кафедра'],['study_group','Группа'],['education_level','Уровень обучения'],['education_program','Программа'],['program_code','Код программы'],['course','Курс','number'],['cohort_year','Год поступления','number'],['position','Должность'],['subdivision','Подразделение'],['valid_until','Билет действителен до','date'],['reregistered_at','Перерегистрация','date']];
const personalFields:[string,string,string?][]=[['iin','ИИН'],['birth_date','Дата рождения','date']];
const filterFields=[['faculty','Факультет'],['department','Кафедра'],['education_program','Программа'],['study_group','Группа'],['course','Курс'],['cohort_year','Год поступления'],['education_level','Уровень обучения']];
const items=ref<any[]>([]),total=ref(0),offset=ref(0),filters=ref<Record<string,string>>({q:'',sort:'full_name'}),options=ref<any>({categories:{},statuses:{}}),branches=ref<any[]>([]),card=ref<any>(null),stats=ref<any>(null),sync=ref<any>(null),ticket=ref<any>(null),busy=ref(false),error=ref(''),notice=ref(''),advanced=ref(false),editing=ref(false),branchName=ref(''),branchCode=ref('');
function query(){return new URLSearchParams(Object.entries(filters.value).filter(([,v])=>v)).toString();}
async function run(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';try{await fn();}catch(e){error.value=String(e);}finally{busy.value=false;}}
async function load(){const result=await props.api('/readers?'+query()+'&offset='+offset.value);items.value=result.items;total.value=result.total;}
async function search(){offset.value=0;await run(load);}
async function open(id:number){await run(async()=>{card.value=await props.api('/readers/'+id);editing.value=false;ticket.value=null;window.scrollTo(0,0);});}
function create(){card.value={full_name:'',category:'student',status:'active',block_reason:'',branch_ids:[],manual_overrides:[],preferred_branch_id:null,field_owners:{}};editing.value=true;ticket.value=null;}
async function save(){await run(async()=>{const source=card.value;const allowed=['full_name','category','status','block_reason','gender','is_teaching_staff','preferred_branch_id','branch_ids','manual_overrides','version',...fields.map(f=>f[0]),...(props.can('readers.personal_data.view')?personalFields.map(f=>f[0]):[])];const body:any={};for(const key of allowed){if(source[key]!==undefined){body[key]=source[key];if(['iin','birth_date','valid_until','reregistered_at','course','cohort_year'].includes(key)&&body[key]==='')body[key]=null;}}const result=await props.api('/readers'+(source.id?'/'+source.id:''),source.id?'PUT':'POST',body);card.value=await props.api('/readers/'+result.id);editing.value=false;notice.value='Карточка сохранена';await load();});}
async function uploadPhoto(event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;if(file.size>3000000){error.value='Фото должно быть не больше 3 МБ';return;}await run(async()=>{const content=await new Promise<string>((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=reject;reader.readAsDataURL(file);});await props.api('/readers/'+card.value.id+'/photo','POST',{content});card.value.has_photo=true;card.value.photoVersion=Date.now();notice.value='Фото сохранено';});}
async function printTicket(){await run(async()=>{ticket.value=await props.api('/readers/'+card.value.id+'/ticket');});}
async function analytics(){await run(async()=>{stats.value=await props.api('/readers/analytics?'+query());});}
async function resolveConflict(id:number){await run(async()=>{await props.api('/readers/conflicts/'+id+'/resolve','POST');sync.value=await props.api('/readers/sync-status');});}
async function searchDirectory(){await run(async()=>{directoryResults.value=[];directorySearched.value=false;const result=await props.api('/readers/source-search?'+new URLSearchParams({source:directorySource.value,q:directoryQuery.value}));directoryResults.value=result.items;directoryTruncated.value=result.truncated;directorySearched.value=true;});}
async function importDirectory(row:any){await run(async()=>{const result=await props.api('/readers/source-import','POST',{source:row.source,entity_type:row.entity_type,external_id:row.external_id});card.value=await props.api('/readers/'+result.id);editing.value=false;directoryOpen.value=false;notice.value=result.warning||'Читатель загружен. Билет и история сохранены.';await load();window.scrollTo(0,0);});}
async function synchronization(){await run(async()=>{sync.value=await props.api('/readers/sync-status');});}
async function exportFile(format:string){await run(async()=>{const response=await fetch('/api/readers/export?'+query()+'&format='+format,{credentials:'same-origin'});if(!response.ok)throw Error('Выгрузка недоступна: '+response.status);const url=URL.createObjectURL(await response.blob());const a=document.createElement('a');a.href=url;a.download='readers.'+format;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});}
async function saveBranch(b:any){await run(async()=>{await props.api('/reader-branches/'+b.id,'PUT',{code:b.code,name:b.name,active:b.active,position:b.position});notice.value='Пункт обслуживания сохранён';});}
async function addBranch(){await run(async()=>{await props.api('/reader-branches','POST',{code:branchCode.value,name:branchName.value});branches.value=await props.api('/reader-branches');branchCode.value='';branchName.value='';});}
function runCount(r:any,key:string){return r.source==='nightly'?Object.values(r.counts).reduce((sum:number,c:any)=>sum+Number(c?.[key]||0),0):Number(r.counts[key]||0);}
function dateTime(v:string){return v?new Date(v.endsWith('Z')||/[+-]\d\d:\d\d$/.test(v)?v:v+'Z').toLocaleString('ru-RU',{timeZone:'Asia/Almaty'}):'—';}
onMounted(()=>run(async()=>{[options.value,branches.value]=await Promise.all([props.api('/readers/options'),props.api('/reader-branches')]);await load();}));
defineExpose({open});
</script>
<template>
<section class="readers-page">
<div class="page-heading"><div><h1>Читатели</h1><p>Локальный реестр · карточки и постоянные читательские билеты</p></div><button v-if="can('readers.registry.edit')" class="primary" @click="create">+ Новый читатель</button></div>
<button v-if="can('readers.source.import')" @click="directoryOpen=!directoryOpen">Найти в AD / Platonus</button>
<section v-if="directoryOpen" class="card" aria-label="Поиск в источниках">
<h2>Загрузить читателя из AD / Platonus</h2><p>Введите ФИО или логин. Выберите человека и загрузите актуальную карточку.</p>
<form class="toolbar" @submit.prevent="searchDirectory"><label>Источник<select v-model="directorySource" @change="directoryResults=[];directorySearched=false"><option value="active_directory">Active Directory</option><option value="platonus">Platonus</option></select></label><label>ФИО или логин<input v-model="directoryQuery" minlength="3" maxlength="100" required></label><button :disabled="busy">{{busy?'Подождите…':'Найти'}}</button><button type="button" @click="directoryOpen=false">Закрыть</button></form>
<p v-if="directorySearched&&!directoryResults.length">Читатель не найден. Проверьте написание или выберите другой источник.</p><p v-if="directoryTruncated">Найдено больше 20 человек. Уточните ФИО или логин.</p>
<table v-if="directoryResults.length"><thead><tr><th>ФИО</th><th>Логин</th><th>Группа / подразделение</th><th></th></tr></thead><tbody><tr v-for="r in directoryResults" :key="r.entity_type+':'+r.external_id"><td>{{r.full_name}}</td><td>{{r.login}}</td><td>{{r.study_group||r.department}}</td><td><button :disabled="busy" @click="importDirectory(r)">{{r.reader_id?'Обновить карточку':'Загрузить читателя'}}</button></td></tr></tbody></table>
</section>
<p v-if="error" role="alert" class="error">{{error}}</p><p v-if="notice" role="status">{{notice}}</p>
<template v-if="card">
<button @click="card=null;ticket=null">← К реестру</button>
<div class="card reader-card"><div class="reader-heading"><img v-if="card.has_photo" :src="'/api/readers/'+card.id+'/photo?v='+(card.photoVersion||0)" alt="Фото читателя" width="90"><div><h2>{{card.full_name||'Новый читатель'}}</h2><p>{{card.ticket_number||'Билет будет присвоен при сохранении'}} · {{card.barcode}}</p><p>{{options.statuses[card.status]}} <span v-if="card.block_reason">— {{card.block_reason}}</span></p></div></div>
<label v-if="card.id&&can('readers.registry.edit')">Добавить/заменить фото<input type="file" accept="image/jpeg,image/png" @change="uploadPhoto"></label><div class="toolbar"><button v-if="card.id&&can('readers.registry.edit')" @click="editing=!editing">{{editing?'Закрыть редактирование':'Редактировать'}}</button><button v-if="card.id&&can('readers.ticket.print')" @click="printTicket">Читательский билет</button><button v-if="card.id&&can('visits.record')" @click="emit('visit',card.barcode)">Зарегистрировать посещение</button></div>
<button v-if="isAdmin&&card.id" @click="accountOptions">Связать вход читателя</button><form v-if="accounts" class="card" @submit.prevent="linkAccount"><p>Создайте пользователя с ролью «Читатель» в разделе пользователей, затем выберите его здесь.</p><select v-model="accountId" aria-label="Учётная запись читателя"><option :value="null">Не связана</option><option v-for="a in accounts" :value="a.id">{{a.name}} · {{a.login}}</option></select><button :disabled="busy">Сохранить связь</button><button type="button" @click="accounts=null">Отмена</button></form>
<form v-if="editing" @submit.prevent="save" class="reader-form">
<label>Категория<select v-model="card.category"><option v-for="(label,key) in options.categories" :value="key">{{label}}</option></select></label>
<label>Статус<select v-model="card.status"><option v-for="(label,key) in options.statuses" :value="key">{{label}}</option></select></label><label>Причина блокировки<input v-model="card.block_reason" maxlength="1000"></label>
<div v-for="[key,label,type] in [...fields,...(can('readers.personal_data.view')?personalFields:[])]" :key="key"><label :for="'reader-'+key">{{label}}</label><small v-if="card.field_owners?.[key]">Источник: {{card.field_owners[key]}} <label><input type="checkbox" :value="key" v-model="card.manual_overrides"> Ручное переопределение</label></small><input :id="'reader-'+key" v-model="card[key]" :type="type||'text'" :required="key==='full_name'" :disabled="!!card.field_owners?.[key]&&!card.manual_overrides.includes(key)"></div>
<label>Пол<select v-model="card.gender"><option value="">Не указан</option><option value="male">Мужской</option><option value="female">Женский</option></select></label>
<label>Основной пункт<select v-model="card.preferred_branch_id"><option :value="null">Не выбран</option><option v-for="b in branches" :value="b.id">{{b.name}}</option></select></label>
<fieldset><legend>Пункты обслуживания</legend><label v-for="b in branches"><input type="checkbox" :value="b.id" v-model="card.branch_ids">{{b.name}}</label></fieldset><button class="primary" :disabled="busy">Сохранить</button>
</form>
<template v-else><dl class="reader-details"><template v-for="[key,label] in [...fields,...(can('readers.personal_data.view')?personalFields:[])]"><dt>{{label}}</dt><dd>{{card[key]||'—'}} <small v-if="card.field_owners?.[key]">(источник: {{card.field_owners[key]}})</small></dd></template></dl><p>Источник: {{card.source}} · Обновление: {{dateTime(card.last_synced_at)}}</p><p v-for="identity in card.identities">{{identity.source}} / {{identity.entity_type}} / {{identity.external_id}}</p><p v-if="card.problems?.length" class="error">Требуют проверки: {{card.problems.map((p:string)=>problemLabels[p]||p).join(', ')}}</p><h3>Посещения: {{card.visits_count||0}}</h3><p>Последнее: {{dateTime(card.last_visit)}}</p><ul><li v-for="v in card.visits">{{dateTime(v.scanned_at)}} · {{branches.find(b=>b.id===v.branch_id)?.name}}</li></ul><p>Входы на сайт: {{card.website_logins===null?'Учётная запись сайта не связана':card.website_logins}}</p><div v-if="card.circulation"><h3>Книговыдача</h3><p>На руках: {{card.circulation.used}} / {{card.circulation.max_loans}} · Просрочек: {{card.circulation.overdue}} · Штрафов: {{card.circulation.fines.length}} · Дел: {{card.circulation.incidents.length}}</p><p v-for="l in card.circulation.loans">{{l.title}} · инв. {{l.inventory_number}} · до {{dateTime(l.due_at)}}</p></div><button disabled>Обходной лист недоступен</button></template>
</div>
<ReaderTicket v-if="ticket" :ticket="ticket" @close="ticket=null" />
</template>
<template v-else>
<form class="card" @submit.prevent="search"><div class="toolbar"><input aria-label="Поиск читателя" v-model="filters.q" placeholder="ФИО, билет, штрихкод, логин или email"><button class="primary" :disabled="busy">Найти</button><button type="button" @click="advanced=!advanced">Фильтры</button></div><div v-if="advanced" class="reader-form">
<label>Аудитория<select v-model="filters.audience"><option value="">Все</option><option value="students">Обучающиеся</option><option value="faculty">ППС</option><option value="staff">Сотрудники</option></select></label>
<label>Категория<select v-model="filters.category"><option value="">Все</option><option v-for="(label,key) in options.categories" :value="key">{{label}}</option></select></label><label>Статус<select v-model="filters.status"><option value="">Все</option><option v-for="(label,key) in options.statuses" :value="key">{{label}}</option></select></label>
<label v-for="[key,label] in filterFields">{{label}}<input v-model="filters[key]"></label><label>Пол<select v-model="filters.gender"><option value="">Любой</option><option value="male">Мужской</option><option value="female">Женский</option></select></label><label>Пункт<select v-model="filters.branch_id"><option value="">Все</option><option v-for="b in branches" :value="String(b.id)">{{b.name}}</option></select></label>
<label>Зарегистрирован с<input type="date" v-model="filters.registered_from"></label><label>По<input type="date" v-model="filters.registered_to"></label><label>Источник<select v-model="filters.source"><option value="">Любой</option><option value="platonus">Platonus</option><option value="active_directory">AD</option></select></label><label>Наличие в источнике<select v-model="filters.source_presence"><option value="">Есть связь</option><option value="absent">Нет связи</option></select></label>
<label>Не заполнено<select v-model="filters.missing"><option value="">Не фильтровать</option><option v-for="f in ['phone','email','faculty','photo',...(can('readers.personal_data.view')?['iin','birth_date']:[])]" :value="f">{{({phone:'Телефон',email:'Email',faculty:'Факультет',photo:'Фото',iin:'ИИН',birth_date:'Дата рождения'} as any)[f]}}</option></select></label><label>Конфликты<select v-model="filters.conflicts"><option value="">Все</option><option value="true">Требуют проверки</option></select></label><label v-if="can('readers.personal_data.view')">Несовпадение ИИН и даты рождения<select v-model="filters.iin_mismatch"><option value="">Все</option><option value="true">Требуют проверки</option></select></label><label>Входы на сайт<select v-model="filters.login_activity"><option value="">Все</option><option value="yes">Есть входы</option><option value="no">Нет подтверждённых входов</option></select></label><label>Сортировка<select v-model="filters.sort"><option value="full_name">ФИО</option><option value="-registered_at">Новые сначала</option><option value="ticket_number">Номер билета</option><option value="status">Статус</option></select></label></div></form>
<div class="toolbar"><span>В выборке: {{total}}</span><button v-if="can('readers.analytics.view')" :disabled="busy" @click="analytics">Аналитика выборки</button><template v-if="can('readers.registry.export')"><button :disabled="busy" @click="exportFile('csv')">CSV</button><button :disabled="busy" @click="exportFile('xlsx')">XLSX</button></template><button v-if="can('readers.sync.admin')" :disabled="busy" @click="synchronization">Синхронизация</button></div>
<div class="card table-wrap"><table><thead><tr><th>Читатель</th><th>Билет / штрихкод</th><th>Категория</th><th>Учёба / работа</th><th>Статус</th></tr></thead><tbody><tr v-for="r in items" :key="r.id"><td><button class="link-button" @click="open(r.id)">{{r.full_name}}</button></td><td>{{r.ticket_number}}<small>{{r.barcode}}</small></td><td>{{options.categories[r.category]}}</td><td>{{r.faculty}}<small>{{r.study_group||r.position}}</small></td><td>{{options.statuses[r.status]}}</td></tr><tr v-if="!items.length"><td colspan="5">Читатели не найдены</td></tr></tbody></table><div class="toolbar"><button :disabled="offset===0||busy" @click="offset-=50;run(load)">Назад</button><span>{{total?offset+1:0}}–{{Math.min(offset+50,total)}} из {{total}}</span><button :disabled="offset+50>=total||busy" @click="offset+=50;run(load)">Далее</button></div></div>
<div v-if="stats" class="card"><h2>Аналитика текущей выборки</h2><p>Читателей: {{stats.total}}</p><div class="reader-form"><div v-for="key in ['category','faculty','course','status','branches']"><h3>{{({category:'Категория',faculty:'Факультет',course:'Курс',status:'Статус',branches:'Пункты'} as any)[key]}}</h3><p v-for="row in stats[key]">{{options.categories[row.label]||options.statuses[row.label]||row.label}}: {{row.count}}</p></div></div><p>Не заполнено: <span v-for="(n,key) in stats.missing">{{missingLabels[String(key)]||key}} — {{n}}; </span></p><h3>Регистрации за 12 месяцев (текущая выборка)</h3><p v-for="r in stats.registrations">{{r.month}}: {{r.count}}</p><p>Активность с {{stats.activity_period.from}} по {{stats.activity_period.to}}: посещений {{stats.physical_visits_30_days}}, входов на сайт {{stats.website_logins_30_days}}.</p><p>{{stats.website_logins}}</p></div>
<div v-if="sync" class="card"><h2>Синхронизация</h2><p>AD: {{sync.ad_enabled?'включён':'отключён'}} · Platonus: {{sync.platonus_enabled?'включён':'отключён'}}</p><p v-if="!sync.status_mapping_confirmed">Соответствия статусов Platonus не подтверждены. Автоматическое приостановление запрещено.</p><p>Читатели загружаются из Active Directory и Platonus: сначала AD, затем недостающие люди из Platonus, затем ИИН и даты рождения студентов. Повторная загрузка обновляет карточки и сохраняет номера билетов.</p><p>Ночное обновление: {{sync.nightly_enabled?'каждый день в '+sync.nightly_time+' (Алматы) при работающем сервисе расписания':'не настроено'}}. Реестр и посещения работают с уже загруженными данными даже при недоступности источников.</p><p v-for="(r,source) in sync.last_success">{{sourceLabels[String(source)]||source}} — последний успешный запуск: {{r?dateTime((r as any).ended_at):'ещё не было'}}</p><p v-if="!sync.runs.length">Запусков ещё не было.</p><div v-for="r in sync.runs"><strong>{{sourceLabels[r.source]||r.source}} · {{runLabels[r.status]||r.status}} · {{dateTime(r.started_at)}}</strong><p>Прочитано: {{runCount(r,'read')}} · Создано: {{runCount(r,'created')}} · Обновлено: {{runCount(r,'updated')}} · Приостановлено: {{runCount(r,'suspended')}} · Ошибок: {{runCount(r,'errors')}}</p><p>{{r.message}}</p></div><h3>Требуют проверки</h3><p v-for="c in sync.conflicts">{{c.source}} / {{c.entity_type}} / {{c.external_id}}: {{problemLabels[c.code]||c.code}} <button :disabled="busy" @click="resolveConflict(c.id)">Проверено</button></p></div>
<details v-if="can('readers.registry.edit')" class="card"><summary>Пункты обслуживания</summary><div class="toolbar" v-for="b in branches"><span>{{b.code}}</span><input aria-label="Название существующего пункта" v-model="b.name"><label><input type="checkbox" v-model="b.active"> Активен</label><button @click="saveBranch(b)">Сохранить пункт</button></div><form class="toolbar" @submit.prevent="addBranch"><input v-model="branchCode" placeholder="Код, например MAIN" required><input v-model="branchName" placeholder="Название пункта" required><button :disabled="busy">Добавить пункт</button></form></details>
</template>
</section>
